nginx_config:
daemon off;
master_process on;
worker_processes 2;
pid /tmp/aegisx-bench-5pfymgva/nginx-main.pid;
error_log /tmp/aegisx-bench-5pfymgva/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-5pfymgva/body;
    proxy_temp_path /tmp/aegisx-bench-5pfymgva/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;
    proxy_cache_path /tmp/aegisx-bench-5pfymgva/cache-nginx-main levels=1 keys_zone=zone:16m max_size=128m inactive=60s use_temp_path=off;
    upstream origin { server 10.42.1.170:3800; keepalive 256; }
    server {

        listen 10.42.1.79:21005   reuseport;
        location / {
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host 10.42.1.170:3800;
            proxy_cache zone;
            proxy_cache_valid 200 60s;
            proxy_no_cache $http_authorization;
            proxy_cache_bypass $http_authorization;
            proxy_pass http://origin;
        }
    }
}
